  | { type: "refusal"; refusal: string }
// eslint-disable-next-line complexity
export function translateResponsesNonStreaming(
  resp: ResponsesResponse,
): ChatCompletionResponse {
  let textContent = ""
  let refusalText = ""
  let reasoningText = ""
  const toolCalls: Array<ToolCall> = []
  for (const item of resp.output) {
    switch (item.type) {
      case "message": {
        for (const content of item.content) {
          if (content.type === "output_text") textContent += content.text
          else refusalText += content.refusal
        }
        break
      }
      case "function_call": {
        toolCalls.push({
          id: item.call_id,
          type: "function",
          function: { name: item.name, arguments: item.arguments },
        })
        break
      }
      case "reasoning": {
        // Extract reasoning summary text if available
        if (item.summary && item.summary.length > 0) {
          reasoningText += item.summary.map((s) => s.text).join("\n")
        }
        break
      }
      // No default
    }
    // Skip other unknown item types
  }
  let finishReason: "stop" | "length" | "tool_calls" | "content_filter" = "stop"
  if (toolCalls.length > 0) finishReason = "tool_calls"
  else if (refusalText || resp.incomplete_details?.reason === "content_filter")
    finishReason = "content_filter"
  else if (resp.incomplete_details?.reason === "max_output_tokens")
    finishReason = "length"
  return {
    id: resp.id,
    object: "chat.completion",
    created: resp.created_at ?? Math.floor(Date.now() / 1000),
    model: resp.model,
    choices: [
      {
        index: 0,
        message: {
          role: "assistant",
          content: textContent || null,
          ...(refusalText ? { refusal: refusalText } : {}),
          ...(reasoningText ? { reasoning_text: reasoningText } : {}),
          ...(toolCalls.length > 0 ? { tool_calls: toolCalls } : {}),
        },
        logprobs: null,
        finish_reason: finishReason,
      },
    ],
    usage:
      resp.usage ?
        {
          prompt_tokens: resp.usage.input_tokens,
          completion_tokens: resp.usage.output_tokens,
          total_tokens: resp.usage.total_tokens,
        }
      : undefined,
    copilot_usage: normalizeCopilotUsage(resp.copilot_usage),
  }
}
